'use strict';

// MODULES //

var reinterpret = require( '@stdlib/strided/base/reinterpret-complex128' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Calculates the dot product of two double-precision complex floating-point vectors.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Complex128Array} x - first input array
* @param {integer} strideX - `x` stride length
* @param {Complex128Array} y - second input array
* @param {integer} strideY - `y` stride length
* @returns {Complex128} dot product
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
*
* var x = new Complex128Array( [ 4.0, 2.0, -3.0, 5.0, -1.0, 7.0 ] );
* var y = new Complex128Array( [ 2.0, 6.0, -1.0, -4.0, 8.0, 9.0 ] );
*
* var z = zdotu( 3, x, 1, y, 1 );
* // returns <Complex128>[ -52.0, 82.0 ]
*/
function zdotu( N, x, strideX, y, strideY ) {
	var viewX = reinterpret( x, 0 );
	var viewY = reinterpret( y, 0 );
	var obj = addon( N, viewX, strideX, viewY, strideY );
	return new Complex128( obj.re, obj.im );
}


// EXPORTS //

module.exports = zdotu;
